race_days" value="<?php echo e(data_get($account?->metadata,'invoice_grace_days',14)); ?>" class="mt-1 w-full rounded-xl border-slate-300"></label></div><label class="flex items-center gap-3 rounded-xl border p-3 text-sm"><input type="checkbox" name="sponsor_ai_usage" value="1" <?php if((bool)data_get($account?->metadata,'sponsor_ai_usage')): echo 'checked'; endif; ?>> <span><strong>Institution-sponsored AI</strong><span class="block text-xs text-slate-500">AI usage can be funded from the institution's commercial balance.</span></span></label><button class="acad-primary-button">Save commercial setup</button></form></section>
